package com.hostelcheck.backend.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="inspection_requests")
public class InspectionRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long propertyId; @Column(nullable=false) private Long studentId; @Column(nullable=false) private String studentName; @Column(nullable=false) private String studentPhone; @Column(length=1000) private String message; @Column(nullable=false) private String status="PENDING"; private LocalDateTime createdAt=LocalDateTime.now(); public InspectionRequest(){}
 public Long getId(){return id;} public Long getPropertyId(){return propertyId;} public void setPropertyId(Long v){propertyId=v;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public String getStudentPhone(){return studentPhone;} public void setStudentPhone(String v){studentPhone=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
